\[
f(n, k) = \begin{cases}
\binom{n+k}{n} - \binom{n+k-2}{n} - \binom{n + \frac{k}{2}}{n} + \binom{n -2 + \frac{k}{2}}{n} & \text{ if $k$ is even} \\
\binom{n+k}{n} - \binom{n+k-2}{n} - 2 \binom{n + \frac{k-1}{2}}{n} +  2 \binom{n + \frac{k-3}{2}}{n-1} & \text{ if $k$ is odd.}
\end{cases}
\]
Choose any integer $N \geq f(n,k)$. Then there exist linear forms $L_1,\dots,L_N \in \ensuremath{\mathbb{K}}[x_0,\dots,x_n] = R$ satisfying

\begin{itemize}

\item no $n+1$ of the linear forms have a common zero, and

\item $R/(L_1^k,\dots,L_N^k)$ fails the WLP from degree $k-1$ to degree $k$.

\end{itemize}

